// spec: specs/contact-login-return.md (3.3–3.6) · кейсы: .qa/tests/contact-login-return/CONTACT-AUTH-10.md, CONTACT-AUTH-11.md
// seed: tests/seed.user.spec.ts · прод, вошедший user. «שלח הודעה» НЕ нажимается ни в одном тесте (реальное сообщение
// чужому продавцу). Все не-GET запросы отклоняются — надёжно только в Chromium → только @desktop / @android.
// Возврат после входа имитируется черновиком в sessionStorage (такой же пишет сайт, CONTACT-AUTH-08);
// реальный вход SMS/Google/регистрация — вручную пользователем.
import { test, expect } from '@playwright/test';
import {
  prepareReadOnly, assertUserSessionFresh, seedDraft, readDraft, contactForm, fields, expectFormStaysClosed,
  DISCREET_ID, DISCREET_URL, OTHER_ID, QA_FIELDS, LOAD,
} from './contact-draft.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test.describe('Форма «יצירת קשר עם המוכר» — возврат в форму после входа', () => {
  test.beforeEach(async ({ page }) => {
    assertUserSessionFresh();
    await prepareReadOnly(page);
  });

  for (const device of ['@desktop', '@android']) {
    test(`После входа форма открывается сама с сообщением из черновика; крестик удаляет черновик, после обновления не открывается #3f0a85 ${device} @prod-safe`, async ({ page }) => {
      await seedDraft(page, { businessId: DISCREET_ID });
      await page.goto(DISCREET_URL);

      const form = contactForm(page);
      await expect(form, 'форма открылась сама').toBeVisible(LOAD);
      const f = fields(form);
      await expect(f.message, 'сообщение — из черновика').toHaveValue(QA_FIELDS.message);
      await expect(f.name, 'имя заполнено (профиль или введённое)').not.toHaveValue('');
      await expect(f.email, 'email заполнен (профиль или введённое)').not.toHaveValue('');
      await expect(form.getByText('עליך להתחבר'), 'нет требования войти').toHaveCount(0);
      await expect(form.getByRole('button', { name: 'שלח הודעה' }), 'можно дослать — кнопка активна (НЕ нажимаем)').toBeEnabled();

      await form.getByRole('button', { name: 'Close' }).click();
      await expect(form, 'форма закрылась').toBeHidden();
      expect(await readDraft(page), 'черновик удалён после крестика').toBeNull();

      await page.reload();
      await expectFormStaysClosed(page);
    });
  }

  test('Черновик старше 30 мин — форма сама не открывается #3f0a85 @android @prod-safe', async ({ page }) => {
    await seedDraft(page, { businessId: DISCREET_ID, ageMs: 31 * 60_000 });
    await page.goto(DISCREET_URL);
    await expectFormStaysClosed(page);
  });

  test('Черновик другого объявления — форма сама не открывается #3f0a85 @android @prod-safe', async ({ page }) => {
    await seedDraft(page, { businessId: OTHER_ID });
    await page.goto(DISCREET_URL);
    await expectFormStaysClosed(page);
  });

  test('Escape закрывает открывшуюся форму и удаляет черновик #3f0a85 @android @prod-safe', async ({ page }) => {
    await seedDraft(page, { businessId: DISCREET_ID });
    await page.goto(DISCREET_URL);
    const form = contactForm(page);
    await expect(form, 'форма открылась сама').toBeVisible(LOAD);

    await page.keyboard.press('Escape');

    await expect(form, 'форма закрылась').toBeHidden();
    expect(await readDraft(page), 'черновик удалён после Escape').toBeNull();
  });

  // Известный баг вне объёма #3f0a85: «ביטול» НЕ удаляет черновик — форма снова открывается сама в течение 30 мин
  // (подтверждено 4/4 27.10, предложен отдельный тикет). Требование есть только в комментарии программиста.
  // Не закладываем как ожидаемое: снять fixme, когда баг исправят.
  test.fixme('«ביטול» закрывает форму и удаляет черновик (известный баг — ждёт тикета) #3f0a85 @android @prod-safe', async ({ page }) => {
    await seedDraft(page, { businessId: DISCREET_ID });
    await page.goto(DISCREET_URL);
    const form = contactForm(page);
    await expect(form).toBeVisible(LOAD);
    await form.getByRole('button', { name: 'ביטול' }).click();
    await expect(form).toBeHidden();
    expect(await readDraft(page), 'черновик удалён после «ביטול»').toBeNull();
  });
});
